        C[1][1] = (A[1][0] * B[0][1] + A[1][1] * B[1][1]) % MOD;
        return C;
    }

    // Matrix exponentiation for 2x2 matrix
    static long[][] matPow(long[][] M, long exp) {
        long[][] R = new long[2][2];
        R[0][0] = 1; R[0][1] = 0;
        R[1][0] = 0; R[1][1] = 1;
        while (exp > 0) {
            if ((exp & 1) != 0) R = mul(R, M);
            M = mul(M, M);
            exp >>= 1;
        }
        return R;
    }

    public static void main(String[] args) throws Exception {
