    static final long MOD = 1000000007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long k = fs.nextLong();
        long w = fs.nextLong();

        if (k == 1) {
            // Only one possible string per length; longest substring that is weak subsequence is length-1.
            // Need length-1 = w => length = w+1. Exactly one string.
            System.out.println(1);
            return;
        }

        // For k >= 2, there are infinitely many strings satisfying the condition.
        System.out.println(-1);
    }

    // Fast scanner
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
