public class Main {
    static final long MOD = 1000000007L;

    // Fast exponentiation
    static long modPow(long a, long e) {
        long r = 1;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long k = Long.parseLong(st.nextToken());
        long w = Long.parseLong(st.nextToken());

        if (k == 1) {
            // Only one string of each length; weak subsequence exists iff length >= w+1
            // So max substring that is weak subsequence is length n-1; we need n-1 = w => n = w+1
            // Exactly one string
            System.out.println(1);
            return;
        }

        // For k >= 2, answer is sum_{n=1..w} k^n + (k-1)*k^w
        // Explanation: strings of length <= w have max weak-subsequence-substring length < w
        // Strings of length w+1: exactly those where last char differs from at least one previous char
        // Longer strings always allow longer weak subsequence, so excluded.

        long sum = 0;
        long cur = 1;
        for (long i = 1; i <= w; i++) {
            cur = (cur * k) % MOD;
            sum += cur;
            if (sum >= MOD) sum -= MOD;
        }
        long kw = cur; // k^w
        long extra = ((k - 1) % MOD) * kw % MOD;
        long ans = (sum + extra) % MOD;
        System.out.println(ans);
    }
}

